// src/components/ui/LoanDetail.js
import React, { useState, useEffect } from 'react';
import { loansAPI, repaymentsAPI } from '../../services/api';
import { X, CheckCircle, Clock, AlertCircle } from 'lucide-react';

const fmtMoney = (n) => new Intl.NumberFormat('fr-FR').format(n || 0) + ' FCFA';
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('fr-FR') : '—';

const scheduleStatusIcon = (s) => {
  if (s === 'PAID') return <CheckCircle size={13} color="var(--success)" />;
  if (s === 'OVERDUE') return <AlertCircle size={13} color="var(--danger)" />;
  return <Clock size={13} color="var(--gray-400)" />;
};

export default function LoanDetail({ loan, onClose }) {
  const [schedule, setSchedule] = useState([]);
  const [repayments, setRepayments] = useState([]);
  const [tab, setTab] = useState('schedule');
  const [payModal, setPayModal] = useState(null);
  const [payAmount, setPayAmount] = useState('');
  const [payNote, setPayNote] = useState('');
  const [paying, setPaying] = useState(false);
  const [msg, setMsg] = useState('');

  const load = async () => {
    try {
      const [s, r] = await Promise.all([
        loansAPI.getSchedule(loan._id),
        repaymentsAPI.getByLoan(loan._id),
      ]);
      setSchedule(s.data.data);
      setRepayments(r.data.data);
    } catch {}
  };

  useEffect(() => { load(); }, [loan._id]);

  const handlePay = async () => {
    if (!payAmount) return;
    setPaying(true);
    setMsg('');
    try {
      await repaymentsAPI.record({
        loanId: loan._id,
        scheduleId: payModal?._id || undefined,
        amount: parseFloat(payAmount),
        note: payNote,
      });
      setPayModal(null);
      setPayAmount('');
      setPayNote('');
      setMsg('Paiement enregistré avec succès');
      load();
    } catch (err) {
      setMsg(err.response?.data?.message || 'Erreur');
    }
    setPaying(false);
  };

  const totalPaid = repayments.reduce((s, r) => s + r.amount, 0);
  const remaining = (loan.totalRepayable || 0) - totalPaid;

  return (
    <div className="modal-backdrop" onClick={(e) => e.target === e.currentTarget && onClose()}>
      <div className="modal fade-in" style={{ maxWidth: 600 }}>
        <div className="modal-header">
          <h3>Détails du prêt</h3>
          <button onClick={onClose} className="btn btn-icon btn-outline"><X size={15} /></button>
        </div>
        <div className="modal-body" style={{ padding: '16px 24px' }}>
          {msg && <div className={`alert ${msg.includes('succès') ? 'alert-success' : 'alert-danger'}`}>{msg}</div>}

          {/* Summary */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 10, marginBottom: 20 }}>
            {[
              { label: 'Montant', value: fmtMoney(loan.amount) },
              { label: 'Intérêt', value: fmtMoney(loan.interest) },
              { label: 'Total', value: fmtMoney(loan.totalRepayable) },
              { label: 'Restant', value: fmtMoney(Math.max(0, remaining)), danger: remaining > 0 },
            ].map(({ label, value, danger }) => (
              <div key={label} style={{ background: danger ? 'var(--danger-light)' : 'var(--gray-50)', borderRadius: 8, padding: '10px 12px', border: '1px solid var(--gray-200)' }}>
                <div style={{ fontSize: 10, color: 'var(--gray-500)', fontWeight: 600, textTransform: 'uppercase', marginBottom: 2 }}>{label}</div>
                <div style={{ fontSize: 13, fontWeight: 700, color: danger ? 'var(--danger)' : 'var(--gray-900)' }}>{value}</div>
              </div>
            ))}
          </div>

          {/* Progress bar */}
          <div style={{ marginBottom: 20 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 11, color: 'var(--gray-500)', marginBottom: 6 }}>
              <span>Progression ({Math.round((totalPaid / (loan.totalRepayable || 1)) * 100)}%)</span>
              <span>{fmtMoney(totalPaid)} payés</span>
            </div>
            <div style={{ background: 'var(--gray-200)', borderRadius: 4, height: 8, overflow: 'hidden' }}>
              <div style={{
                height: '100%', borderRadius: 4,
                background: loan.status === 'COMPLETED' ? 'var(--success)' : loan.status === 'OVERDUE' ? 'var(--danger)' : 'var(--accent)',
                width: `${Math.min(100, Math.round((totalPaid / (loan.totalRepayable || 1)) * 100))}%`,
                transition: 'width 0.5s ease',
              }} />
            </div>
          </div>

          {/* Tabs */}
          <div style={{ display: 'flex', gap: 4, marginBottom: 16, borderBottom: '1px solid var(--gray-200)', paddingBottom: 0 }}>
            {[['schedule', 'Calendrier'], ['repayments', 'Paiements']].map(([key, label]) => (
              <button key={key} onClick={() => setTab(key)} style={{
                padding: '8px 16px', border: 'none', background: 'transparent',
                fontSize: 13, fontWeight: tab === key ? 600 : 400,
                color: tab === key ? 'var(--primary)' : 'var(--gray-500)',
                borderBottom: tab === key ? '2px solid var(--primary)' : '2px solid transparent',
                cursor: 'pointer', marginBottom: -1,
              }}>{label} ({key === 'schedule' ? schedule.length : repayments.length})</button>
            ))}
          </div>

          {tab === 'schedule' && (
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              <table>
                <thead><tr><th>Mois</th><th>Montant</th><th>Date</th><th>Statut</th><th></th></tr></thead>
                <tbody>
                  {schedule.map((s) => (
                    <tr key={s._id}>
                      <td>Mois {s.monthNumber}</td>
                      <td>{fmtMoney(s.amountDue)}</td>
                      <td>{fmtDate(s.dueDate)}</td>
                      <td>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                          {scheduleStatusIcon(s.status)}
                          <span style={{ fontSize: 12 }}>{s.status === 'PAID' ? 'Payé' : s.status === 'OVERDUE' ? 'En retard' : 'En attente'}</span>
                        </div>
                      </td>
                      <td>
                        {s.status !== 'PAID' && loan.status !== 'COMPLETED' && (
                          <button className="btn btn-accent btn-sm" onClick={() => { setPayModal(s); setPayAmount(String(s.amountDue)); }}>
                            Payer
                          </button>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {tab === 'repayments' && (
            <div style={{ maxHeight: 300, overflowY: 'auto' }}>
              {repayments.length === 0 ? (
                <p style={{ color: 'var(--gray-400)', fontSize: 13, textAlign: 'center', padding: 24 }}>Aucun paiement enregistré</p>
              ) : (
                <table>
                  <thead><tr><th>Montant</th><th>Date</th><th>Note</th></tr></thead>
                  <tbody>
                    {repayments.map((r) => (
                      <tr key={r._id}>
                        <td style={{ fontWeight: 600, color: 'var(--success)' }}>{fmtMoney(r.amount)}</td>
                        <td>{fmtDate(r.paidAt)}</td>
                        <td style={{ color: 'var(--gray-500)' }}>{r.note || '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
            </div>
          )}
        </div>

        {/* Pay modal nested */}
        {payModal && (
          <div style={{ padding: '0 24px 20px' }}>
            <div style={{ background: 'var(--accent-light)', borderRadius: 10, padding: 16, border: '1px solid #b2dfdb' }}>
              <div style={{ fontWeight: 600, marginBottom: 12, fontSize: 13 }}>Enregistrer paiement — Mois {payModal.monthNumber}</div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12, marginBottom: 10 }}>
                <div className="form-group" style={{ marginBottom: 0 }}>
                  <label>Montant *</label>
                  <input className="form-control" type="number" value={payAmount} onChange={e => setPayAmount(e.target.value)} />
                </div>
                <div className="form-group" style={{ marginBottom: 0 }}>
                  <label>Note (optionnel)</label>
                  <input className="form-control" value={payNote} onChange={e => setPayNote(e.target.value)} placeholder="Note..." />
                </div>
              </div>
              <div style={{ display: 'flex', gap: 8 }}>
                <button onClick={() => setPayModal(null)} className="btn btn-outline btn-sm">Annuler</button>
                <button onClick={handlePay} disabled={paying} className="btn btn-accent btn-sm">
                  {paying ? 'Enregistrement...' : 'Confirmer paiement'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
